import { createContext, useContext, useEffect, useState } from "react";
import { api, getUserId, setUserId, clearUserId } from "./api";

const AuthContext = createContext(null);
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(!!getUserId());

  // if a user id is saved, load that user
  useEffect(() => {
    if (!getUserId()) return;
    api
      .get("/auth/me")
      .then(setUser)
      .catch(clearUserId)
      .finally(() => setLoading(false));
  }, []);

  const authenticate = async (path, body) => {
    const data = await api.post(path, body);
    setUserId(data.user.id);
    setUser(data.user);
  };

  const value = {
    user,
    loading,
    login: (body) => authenticate("/auth/login", body),
    register: (body) => authenticate("/auth/register", body),
    updateUser: (u) => setUser((prev) => ({ ...prev, ...u })),
    logout: () => {
      clearUserId();
      setUser(null);
    },
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
